package com.medtrack.warehouse.entity;
import com.medtrack.shared.model.BaseEntity; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="warehouses") public class Warehouse extends BaseEntity { @Column(nullable=false,unique=true) private String code; @Column(nullable=false) private String name; @Enumerated(EnumType.STRING) @Column(nullable=false) private WarehouseType type; @Column(nullable=false) private String address; private BigDecimal latitude; private BigDecimal longitude; @Column(name="contact_phone") private String contactPhone; @Enumerated(EnumType.STRING) @Column(nullable=false) private WarehouseStatus status; protected Warehouse(){} public Warehouse(String code,String name,WarehouseType type,String address,BigDecimal lat,BigDecimal lon,String phone,WarehouseStatus status){this.code=code;this.name=name;this.type=type;this.address=address;latitude=lat;longitude=lon;contactPhone=phone;this.status=status;} public void update(String name,WarehouseType type,String address,BigDecimal lat,BigDecimal lon,String phone,WarehouseStatus status){this.name=name;this.type=type;this.address=address;latitude=lat;longitude=lon;contactPhone=phone;this.status=status;} public String getCode(){return code;} public String getName(){return name;} public WarehouseType getType(){return type;} public String getAddress(){return address;} public BigDecimal getLatitude(){return latitude;} public BigDecimal getLongitude(){return longitude;} public String getContactPhone(){return contactPhone;} public WarehouseStatus getStatus(){return status;} }
